CREATE TABLE IF NOT EXISTS display_devices (id bigserial PRIMARY KEY, hospital_id bigint NOT NULL REFERENCES hospitals(id) ON DELETE CASCADE, name text NOT NULL, location text, device_code uuid NOT NULL DEFAULT gen_random_uuid(), enabled boolean NOT NULL DEFAULT true, token_percent integer NOT NULL DEFAULT 50 CHECK (token_percent BETWEEN 0 AND 100), ad_percent integer NOT NULL DEFAULT 50 CHECK (ad_percent BETWEEN 0 AND 100), ad_rotation_seconds integer NOT NULL DEFAULT 10 CHECK (ad_rotation_seconds BETWEEN 3 AND 300), show_next_tokens boolean NOT NULL DEFAULT true, show_sound boolean NOT NULL DEFAULT false, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now(), UNIQUE(hospital_id, device_code))